import type { FeatureCollection, Point } from "geojson";
import { PLACES_URL } from "../config";

export type MunicipalityType = "mesto" | "mestys" | "obec";

/** One část obce (town, village or hamlet) — its centre point. */
export interface PlaceProps {
  name: string;
  municipality: string;
  municipalityId: number;
  type: MunicipalityType;
  /** Okres (district). */
  district: string;
  /** True for the part that represents the whole municipality (its centre). */
  main: boolean;
}

export type Places = FeatureCollection<Point, PlaceProps>;

/** Generated by scripts/fetch-places.mjs from ČÚZK RÚIAN. */
export async function loadPlaces(): Promise<Places> {
  const res = await fetch(PLACES_URL);
  if (!res.ok) throw new Error(`Failed to load places: ${res.status}`);
  return res.json();
}
